mapper.select:
SELECT fz.id, fz.dji_fly_zone_id AS djiFlyZoneId, fz.name, fz.category, fz.shape, fz.center_lat AS centerLat, fz.center_lng AS centerLng, fz.radius, fz.max_altitude AS maxAltitude, fz.description, fz.source, fz.creator_id AS creatorId, u.user_name AS creatorName, fz.enabled, fz.create_time AS createTime, fz.modification_time AS modificationTime FROM fly_zones fz LEFT JOIN users u ON fz.creator_id = u.user_id
AND fz.name LIKE CONCAT('%',#{keyword},'%') AND fz.category = #{category}
ORDER BY fz.create_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM fly_zones fz

    AND fz.name LIKE CONCAT('%',#{keyword},'%')
    AND fz.category = #{category}

mapper.update:
UPDATE fly_zones
name = #{name}, category = #{category}, shape = #{shape}, center_lat = #{centerLat}, center_lng = #{centerLng}, radius = #{radius}, polygon_points = #{polygonPoints}, max_altitude = #{maxAltitude}, description = #{description}, enabled = #{enabled}, modification_time = #{modificationTime}
WHERE id = #{id}
